/// `AfterSideTurnStart` bus.
pub(crate) fn on_after_side_turn_start_blood_vial(
    state: &mut CombatState,
    side: Side,
) -> EffectResult {
    if side != Side::Player || state.turn_number() != 1 {
        return EffectResult::NotImplemented;
    }
    if !player_owns_relic(state, crate::RelicKind::BloodVial) {
        return EffectResult::NotImplemented;
    }
    let Some(uid) = state.player.creature_uid else {
        return EffectResult::NotImplemented;
    };
    state.creature_heal(uid, 2);
    EffectResult::Resolved
}

